export const chambersBySlug: Record<string, Chamber> = Object.fromEntries(chambers.map((c) => [c.slug, c]));

export function neighbors(slug: string) {
  const i = chambers.findIndex((c) => c.slug === slug);
  return { prev: chambers[i - 1], next: chambers[i + 1] };
}
